/**
 * The browser demo's planner and DSKY must reproduce the Python planner and
 * AGC engine exactly, on vectors generated by scripts/write_demo_vectors.py.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { CATALOG_VERSION, planCommand, postconditionMatches, type DemoCommand } from '../lib/demo/catalog';
import { Dsky, type DskyKeyName } from '../lib/demo/dsky';

const REPO = path.resolve(import.meta.dirname, '..', '..');

interface VectorStep {
  command?: DemoCommand;
  plan_error?: string;
  plan?: {
    command_id: string;
    keys: DskyKeyName[];
    critical_reasons: string[];
    postcondition: unknown;
  };
  keys?: DskyKeyName[];
  gap_ms?: number;
  key_results?: Array<{ key: DskyKeyName; accepted: boolean; error: string | null }>;
  state_before: unknown;
  state_after: unknown;
  postcondition_matched?: boolean;
}

interface VectorDoc {
  catalog_version: string;
  key_cadence_ms: number;
  scenarios: Array<{ id: string; steps: VectorStep[] }>;
}

const doc = JSON.parse(readFileSync(path.join(REPO, 'contracts/vectors/dsky-demo.json'), 'utf8')) as VectorDoc;

describe('demo planner and DSKY match the Python reference', () => {
  it('uses the same catalog version', () => {
    expect(CATALOG_VERSION).toBe(doc.catalog_version);
  });

  doc.scenarios.forEach((scenario) => {
    it(`scenario ${scenario.id}`, () => {
      const dsky = new Dsky();
      let clock = 0;
      scenario.steps.forEach((step, stepIndex) => {
        const label = `${scenario.id} step ${stepIndex}`;
        expect(dsky.view(), `${label} state_before`).toEqual(step.state_before);
        let keys: DskyKeyName[];
        if (step.command) {
          const result = planCommand(step.command, dsky.view());
          if (step.plan_error) {
            expect(result.ok ? 'ok' : result.error, label).toBe(step.plan_error);
            expect(dsky.view(), `${label} state_after`).toEqual(step.state_after);
            return;
          }
          expect(result.ok, label).toBe(true);
          if (!result.ok) return;
          expect(result.plan.commandId, label).toBe(step.plan!.command_id);
          expect(result.plan.keys, label).toEqual(step.plan!.keys);
          expect(result.plan.criticalReasons, label).toEqual(step.plan!.critical_reasons);
          expect(result.plan.postcondition, label).toEqual(step.plan!.postcondition);
          keys = result.plan.keys;
        } else {
          keys = step.keys!;
        }
        const results = keys.map((key) => {
          clock += step.gap_ms ?? doc.key_cadence_ms;
          const r = dsky.press(key, clock);
          return { key, accepted: r.accepted, error: r.error };
        });
        expect(results, `${label} key results`).toEqual(step.key_results);
        expect(dsky.view(), `${label} state_after`).toEqual(step.state_after);
        if (step.plan) {
          const planned = planCommand(step.command!, step.state_before as ReturnType<Dsky['view']>);
          expect(planned.ok && postconditionMatches(planned.plan.postcondition, dsky.view())).toBe(
            step.postcondition_matched,
          );
        }
      });
    });
  });

  it('rejects keys closer than the catalog cadence and while KEY REL is lit', () => {
    const dsky = new Dsky();
    expect(dsky.press('VERB', 100).error).toBeNull();
    expect(dsky.press('DIGIT_2', 150)).toEqual({ accepted: false, error: 'KEY_CADENCE' });
    dsky.setKeyRel(true);
    expect(dsky.press('DIGIT_2', 400)).toEqual({ accepted: false, error: 'KEY_REL_ACTIVE' });
  });
});
